<template>
  <main class="create-group-workspace">
    <header><button @click="back"><i class="fa fa-angle-left"></i> 返回消息中心</button><div><strong>创建群聊</strong><span>选择成员、设置群资料并确认创建</span></div></header>
    <nav><button :class="{active:step===1}" @click="step=1"><b>1</b> 选择成员</button><i></i><button :class="{active:step===2}" :disabled="!selectedIds.length" @click="step=2"><b>2</b> 设置群资料</button><i></i><button :class="{active:step===3}" :disabled="!name.trim()||!selectedIds.length" @click="step=3"><b>3</b> 确认创建</button></nav>
    <section v-if="step===1" class="member-step"><div><label class="search"><i class="fa fa-search"></i><input v-model="keyword" autofocus placeholder="搜索好友昵称、备注或账号" /></label><p>至少选择 1 位好友（加上自己至少 2 人）</p><div v-if="loading" class="loading"><i class="fa fa-circle-o-notch fa-spin"></i> 正在加载好友</div><button v-for="friend in filteredFriends" :key="friend.friendId" :class="{selected:selectedIds.includes(friend.friendId)}" @click="toggleFriend(friend.friendId)"><span><img v-if="friend.avatarPath" :src="friend.avatarPath" alt=""/><b v-else>{{ friendLabel(friend).slice(0,1) }}</b></span><strong>{{ friendLabel(friend) }}</strong><small>{{ friend.account||friend.friendId }}</small><i :class="selectedIds.includes(friend.friendId)?'fa fa-check-circle':'fa fa-circle-o'"></i></button></div><aside><strong>已选成员（{{ selectedIds.length }}）</strong><p v-if="!selectedIds.length">从左侧选择好友</p><span v-for="friend in selectedFriends" :key="friend.friendId"><img v-if="friend.avatarPath" :src="friend.avatarPath" alt=""/><b v-else>{{ friendLabel(friend).slice(0,1) }}</b><button @click="toggleFriend(friend.friendId)"><i class="fa fa-times"></i></button></span></aside><footer><button class="primary" :disabled="!selectedIds.length" @click="step=2">下一步</button></footer></section>
    <section v-else-if="step===2" class="profile-step"><span class="avatar-preview"><img v-if="avatarUrl" :src="avatarUrl" alt="群头像预览"/><i v-else class="fa fa-users"></i></span><label>群聊名称<input v-model="name" maxlength="30" placeholder="例如：产品研发群" autofocus /></label><small>{{ name.length }}/30</small><label>群头像地址（可选）<input v-model="avatarUrl" placeholder="粘贴文件服务返回的可访问 URL" /></label><p class="notice"><i class="fa fa-info-circle"></i> 当前文件服务尚未提供独立的“群头像上传/裁剪”资源接口；这里仅接受已上传图片的授权 URL，空缺时客户端将使用成员拼图头像。</p><div class="profile-actions"><button @click="step=1">上一步</button><button class="primary" :disabled="!name.trim()" @click="step=3">下一步</button></div></section>
    <section v-else class="confirm-step"><span class="avatar-preview"><img v-if="avatarUrl" :src="avatarUrl" alt=""/><i v-else class="fa fa-users"></i></span><h2>{{ name.trim() || '未命名群聊' }}</h2><p>包含你和 {{ selectedIds.length }} 位好友，共 {{ selectedIds.length+1 }} 人</p><div class="selected-summary"><span v-for="friend in selectedFriends" :key="friend.friendId">{{ friendLabel(friend) }}</span></div><div><button @click="step=2">上一步</button><button class="primary" :disabled="submitting" @click="create"><i v-if="submitting" class="fa fa-circle-o-notch fa-spin"></i><i v-else class="fa fa-check"></i> 创建群聊</button></div></section>
    <div v-if="error" class="error"><i class="fa fa-exclamation-circle"></i>{{ error }}</div>
  </main>
</template>

<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { listFriendsApi } from '@/api/im/friendApi'
import { useAuthStore } from '@/stores/authStore'
import { useMessageCenterStore, type MessageCenterFriend } from '@/stores/messageCenterStore'

const router=useRouter(),auth=useAuthStore(),store=useMessageCenterStore()
const step=ref(1),keyword=ref(''),friends=ref<MessageCenterFriend[]>([]),selectedIds=ref<string[]>([]),name=ref(''),avatarUrl=ref(''),loading=ref(false),submitting=ref(false),error=ref('')
const filteredFriends=computed(()=>friends.value.filter(friend=>!keyword.value||`${friendLabel(friend)} ${friend.account||''}`.toLowerCase().includes(keyword.value.toLowerCase())))
const selectedFriends=computed(()=>friends.value.filter(friend=>selectedIds.value.includes(friend.friendId)))
onMounted(async()=>{loading.value=true;try{const userId=auth.user.id;if(!userId)throw new Error('请重新登录后创建群聊');const response=await listFriendsApi(userId);if(response.code!==200)throw new Error(response.message||'好友列表加载失败');friends.value=response.data||[]}catch(e){error.value=e instanceof Error?e.message:'好友列表加载失败'}finally{loading.value=false}})
function friendLabel(friend:MessageCenterFriend){return friend.remark||friend.username||friend.account||friend.friendId}
function toggleFriend(id:string){selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(item=>item!==id):[...selectedIds.value,id]}
function back(){if(step.value>1){step.value--;return}router.push('/app/notifications')}
async function create(){if(!name.value.trim()||!selectedIds.value.length)return;submitting.value=true;error.value='';try{const group=await store.createGroup(name.value.trim(),selectedIds.value,avatarUrl.value.trim()||undefined);router.replace({path:'/app/notifications',query:{conversation:group.conversationId}})}catch(e){error.value=e instanceof Error?e.message:'创建群聊失败'}finally{submitting.value=false}}
</script>

<style scoped>
.create-group-workspace{width:min(1000px,calc(100vw - 32px));min-height:640px;margin:24px auto;padding:24px;border:1px solid var(--border-color,#e6e9ef);border-radius:18px;background:var(--bg-color,#fff);color:var(--text-color,#18202b);box-shadow:0 14px 40px #22314b12}.create-group-workspace>header{display:flex;align-items:center;gap:18px}.create-group-workspace>header>button{color:#5468ff}.create-group-workspace>header div{display:flex;flex-direction:column}.create-group-workspace>header span,.member-step p,.profile-step small,.notice,.confirm-step p{color:#718096;font-size:12px}.create-group-workspace>nav{display:flex;align-items:center;justify-content:center;gap:10px;margin:28px 0}.create-group-workspace>nav button{display:flex;align-items:center;gap:6px;color:#8a95a5}.create-group-workspace>nav button.active{color:#5468ff;font-weight:700}.create-group-workspace>nav b{width:25px;height:25px;display:grid;place-items:center;border-radius:50%;background:#edf0ff}.create-group-workspace>nav button.active b{background:#5468ff;color:#fff}.create-group-workspace>nav i{width:60px;height:1px;background:#e6e9ef}.member-step{position:relative;min-height:460px;display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:20px;padding-bottom:62px}.search{height:42px;display:flex;align-items:center;gap:8px;padding:0 12px;border-radius:10px;background:#f3f5f8;color:#738096}.search input{min-width:0;flex:1;background:transparent;color:inherit;outline:0}.member-step>div>button{width:100%;display:grid;grid-template-columns:42px minmax(0,1fr) minmax(0,1fr) 22px;align-items:center;gap:9px;padding:8px;border-bottom:1px solid #edf0f3;text-align:left}.member-step>div>button:hover,.member-step>div>button.selected{background:#eef0ff}.member-step>div>button>span,.member-step aside>span{width:38px;height:38px;display:grid;place-items:center;overflow:hidden;border-radius:50%;background:#e9edf5}.member-step img,.member-step aside img{width:100%;height:100%;object-fit:cover}.member-step>div>button small{color:#718096;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.member-step>div>button>i{color:#5468ff}.member-step aside{padding:14px;border-radius:12px;background:#f7f8fa}.member-step aside>span{position:relative;display:inline-grid;margin:9px 5px 0 0}.member-step aside>span button{position:absolute;right:-4px;top:-4px;width:16px;height:16px;border-radius:50%;background:#273142;color:#fff;font-size:9px}.member-step footer{position:absolute;right:0;bottom:0}.primary{padding:9px 15px;border-radius:9px;background:#5468ff!important;color:#fff!important}.primary:disabled{opacity:.5}.profile-step,.confirm-step{width:min(500px,100%);margin:45px auto;display:grid;justify-items:center;gap:10px;text-align:center}.avatar-preview{width:90px;height:90px;display:grid;place-items:center;overflow:hidden;border-radius:28px;background:linear-gradient(135deg,#5468ff,#8b5cf6);color:#fff;font-size:36px}.avatar-preview img{width:100%;height:100%;object-fit:cover}.profile-step label{width:100%;display:grid;gap:6px;text-align:left;font-size:12px}.profile-step input{height:42px;padding:0 11px;border:1px solid #e6e9ef;border-radius:9px;outline-color:#5468ff}.notice{padding:10px;border-radius:9px;background:#f0f3ff;text-align:left;line-height:1.5}.profile-actions,.confirm-step>div:last-child{width:100%;display:flex;justify-content:space-between;gap:9px}.profile-actions>button,.confirm-step>div:last-child>button:not(.primary){padding:9px 14px;border-radius:9px;background:#f0f2f5}.selected-summary{display:flex;flex-wrap:wrap;justify-content:center;gap:6px;margin:8px 0}.selected-summary span{padding:5px 8px;border-radius:9px;background:#f0f2f5;color:#4c5969;font-size:12px}.loading{padding:30px;color:#718096}.error{margin-top:16px;padding:10px;border-radius:9px;background:#fff0f1;color:#d33b43;font-size:12px}@media(max-width:700px){.create-group-workspace{width:100%;min-height:100dvh;margin:0;border:0;border-radius:0}.member-step{grid-template-columns:1fr}.member-step aside{max-height:130px;overflow:auto}.create-group-workspace>nav i{width:18px}.create-group-workspace>nav button{font-size:11px}.create-group-workspace>nav button:not(.active){font-size:0}.create-group-workspace>nav button:not(.active) b{font-size:12px}}
</style>
